+
+    private List<StackPane> buildUnstyledChain(int depth) {
+        List<StackPane> chain = new ArrayList<>(depth);
+        Pane current = root;
+        for (int i = 0; i < depth; i++) {
+            StackPane pane = new StackPane();
+            current.getChildren().add(pane);
+            chain.add(pane);
+
+            current = pane;
+        }
+        return chain;
+    }
